#!/bin/bash
#
# Attempts to locate a compatible module for the provided module@version in the
# locked module list
#
# Copyright (c) 2015 Silk Labs, Inc.
# All Rights Reserved.
# Confidential and Proprietary - Silk Labs, Inc.

mod_ver="$1"
if [[ -z $mod_ver ]]; then
  echo "Usage: $0 <module name@semver range>" >&2
  echo 1
fi

source $(dirname $0)/../../../../tools/gnu.sh

LOCKED_NODE_MODULES=$(readlink -f $(dirname $0)/node_modules/modules)

semver=$(readlink -f $(dirname $0)/node_modules/.bin/semver)
if [[ ! -x $semver ]]; then
  echo Error: semver missing >&2
  exit 1
fi

mod=${mod_ver%%@*}
ver=${mod_ver##*@}

if [[ ! -d $LOCKED_NODE_MODULES ]]; then
  echo Warning: $LOCKED_NODE_MODULES does not exist. >&2
  exit 1
fi

if [[ ! -d $LOCKED_NODE_MODULES/$mod ]]; then
  echo Warning: $mod is missing from $LOCKED_NODE_MODULES/... >&2
  exit 1
fi

locked_ver=
for candidate_ver in $(ls $LOCKED_NODE_MODULES/$mod | sort -u); do
  if $semver $candidate_ver -r $ver > /dev/null; then
    locked_ver=$candidate_ver
    break;
  fi
done

if [[ -z $locked_ver ]]; then
  echo Warning: $mod_ver is missing from $LOCKED_NODE_MODULES/... >&2
  exit 1
fi

real_locked_ver=$(node -p "require('$LOCKED_NODE_MODULES/$mod/$locked_ver/$mod/package.json').version")
if [[ "$real_locked_ver" != "$locked_ver" ]]; then
  echo Warning: Version mismatch at $LOCKED_NODE_MODULES/$mod/$locked_ver >&2
  echo "         package.json says $real_locked_ver" >&2
  exit 1
fi

echo $LOCKED_NODE_MODULES/$mod/$locked_ver
exit 0
